package ps.lambda.patterns.chaining;import ps.lambda.patterns.chaining.model.Person;import ps.lambda.patterns.chaining.util.Comparator;import java.util.Objects;import java.util.function.Function;public class PlayWithComparators {    public static void main(String[] args) {        Person mary = new Person("Mary", 28);        Person john = new Person("John", 22);        Person linda = new Person("Linda", 26);        Person james = new Person("James", 32);        Person jamesBis = new Person("James", 26);        Function<Person, String> getName = p -> p.getName();        Comparator<Person> cmpName = (a, b) -> {            return getName.apply(a).compareTo(b.getName());        };        Comparator<Person> cmp =                Comparator.comparing(Person::getName)                        .thenComparing(Person::getAge);        System.out.println("Mary > John : " + (cmp.compare(mary, john) > 0));        System.out.println("John > James : " + (cmp.compare(john, james) > 0));        System.out.println("Linda > John : " + (cmp.compare(linda, john) > 0));        System.out.println("James > James Bis : " + (cmp.compare(james, jamesBis) > 0));    }    static <T, U extends Comparable<U>> Comparator<T> comparing(Function<T, U> key) {        Objects.requireNonNull(key);        return (p1, p2) -> {            U s1 = key.apply(p1);            U s2 = key.apply(p2);            return s1.compareTo(s2);        };    }}